# 12-ingilizce-17 görsel modülü

GORSELLER = {'b1': "<svg viewBox='0 0 760 320' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='320' rx='16' fill='#f8fafc'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='700' fill='#1e3a8a'>How Polite Is Your Request? (Ricanın Kibarlık Basamakları)</text><text x='85' y='222' text-anchor='middle' font-size='10' fill='#475569'>friends, family</text><rect x='30' y='230' width='110' height='50' rx='10' fill='#dbeafe' stroke='#2563eb' stroke-width='2'/><text x='85' y='252' text-anchor='middle' font-size='12' font-weight='700' fill='#1e3a8a'>Can you</text><text x='85' y='268' text-anchor='middle' font-size='12' fill='#1e3a8a'>+ V1...?</text><text x='205' y='192' text-anchor='middle' font-size='10' fill='#475569'>teachers, adults</text><rect x='150' y='200' width='110' height='80' rx='10' fill='#bfdbfe' stroke='#2563eb' stroke-width='2'/><text x='205' y='222' text-anchor='middle' font-size='12' font-weight='700' fill='#1e3a8a'>Could you</text><text x='205' y='238' text-anchor='middle' font-size='12' fill='#1e3a8a'>+ V1...?</text><text x='325' y='162' text-anchor='middle' font-size='10' fill='#475569'>polite, neutral</text><rect x='270' y='170' width='110' height='110' rx='10' fill='#c7d2fe' stroke='#4f46e5' stroke-width='2'/><text x='325' y='192' text-anchor='middle' font-size='12' font-weight='700' fill='#312e81'>Would you</text><text x='325' y='208' text-anchor='middle' font-size='12' fill='#312e81'>+ V1...?</text><text x='445' y='132' text-anchor='middle' font-size='10' fill='#475569'>bigger favors</text><rect x='390' y='140' width='110' height='140' rx='10' fill='#ddd6fe' stroke='#7c3aed' stroke-width='2'/><text x='445' y='162' text-anchor='middle' font-size='12' font-weight='700' fill='#4c1d95'>Could you</text><text x='445' y='178' text-anchor='middle' font-size='12' fill='#4c1d95'>possibly + V1?</text><text x='565' y='102' text-anchor='middle' font-size='10' fill='#475569'>may cause trouble</text><rect x='510' y='110' width='110' height='170' rx='10' fill='#f5d0fe' stroke='#a21caf' stroke-width='2'/><text x='565' y='132' text-anchor='middle' font-size='12' font-weight='700' fill='#701a75'>Would you mind</text><text x='565' y='148' text-anchor='middle' font-size='12' fill='#701a75'>+ V-ing?</text><text x='685' y='72' text-anchor='middle' font-size='10' fill='#475569'>formal e-mails</text><rect x='630' y='80' width='110' height='200' rx='10' fill='#fce7f3' stroke='#db2777' stroke-width='2'/><text x='685' y='102' text-anchor='middle' font-size='11' font-weight='700' fill='#831843'>I'd be grateful</text><text x='685' y='118' text-anchor='middle' font-size='11' fill='#831843'>if you could...</text><text x='685' y='150' text-anchor='middle' font-size='11' font-weight='700' fill='#831843'>I was wondering</text><text x='685' y='166' text-anchor='middle' font-size='11' fill='#831843'>if you could...</text><line x1='40' y1='296' x2='710' y2='296' stroke='#64748b' stroke-width='3'/><polygon points='710,289 724,296 710,303' fill='#64748b'/><text x='40' y='314' font-size='11' font-weight='700' fill='#475569'>less formal (samimi)</text><text x='720' y='314' text-anchor='end' font-size='11' font-weight='700' fill='#475569'>more formal (resmî)</text></svg>", 'b2': "<svg viewBox='0 0 760 330' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='330' rx='16' fill='#f8fafc'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='700' fill='#0f172a'>Two Uses of MIND and How to Answer Them</text><rect x='24' y='48' width='344' height='220' rx='12' fill='#ffffff' stroke='#0284c7' stroke-width='2'/><rect x='24' y='48' width='344' height='34' rx='12' fill='#0284c7'/><text x='196' y='70' text-anchor='middle' font-size='13' font-weight='700' fill='#ffffff'>Asking someone to do something</text><text x='196' y='104' text-anchor='middle' font-size='14' font-weight='700' fill='#075985'>Would you mind + V-ing?</text><text x='196' y='130' text-anchor='middle' font-size='12' fill='#334155'>Would you mind closing the window?</text><rect x='40' y='148' width='312' height='48' rx='10' fill='#dcfce7'/><text x='196' y='168' text-anchor='middle' font-size='12' font-weight='700' fill='#166534'>No, not at all.</text><text x='196' y='186' text-anchor='middle' font-size='11' fill='#166534'>= Tabii, kapatırım. (KABUL)</text><rect x='40' y='206' width='312' height='48' rx='10' fill='#fee2e2'/><text x='196' y='226' text-anchor='middle' font-size='12' font-weight='700' fill='#991b1b'>Sorry, I'm feeling a bit hot.</text><text x='196' y='244' text-anchor='middle' font-size='11' fill='#991b1b'>= Kapatmasam iyi olur. (RET)</text><rect x='392' y='48' width='344' height='220' rx='12' fill='#ffffff' stroke='#7c3aed' stroke-width='2'/><rect x='392' y='48' width='344' height='34' rx='12' fill='#7c3aed'/><text x='564' y='70' text-anchor='middle' font-size='13' font-weight='700' fill='#ffffff'>Asking for permission</text><text x='564' y='100' text-anchor='middle' font-size='13' font-weight='700' fill='#4c1d95'>Do you mind if I + V1?</text><text x='564' y='118' text-anchor='middle' font-size='13' font-weight='700' fill='#4c1d95'>Would you mind if I + V2?</text><text x='564' y='138' text-anchor='middle' font-size='12' fill='#334155'>Would you mind if I opened the window?</text><rect x='408' y='148' width='312' height='48' rx='10' fill='#dcfce7'/><text x='564' y='168' text-anchor='middle' font-size='12' font-weight='700' fill='#166534'>No, go ahead.</text><text x='564' y='186' text-anchor='middle' font-size='11' fill='#166534'>= Açabilirsin. (İZİN VERİLDİ)</text><rect x='408' y='206' width='312' height='48' rx='10' fill='#fee2e2'/><text x='564' y='226' text-anchor='middle' font-size='12' font-weight='700' fill='#991b1b'>Well, actually, I'd rather you didn't.</text><text x='564' y='244' text-anchor='middle' font-size='11' fill='#991b1b'>= Açmasan iyi olur. (İZİN YOK)</text><rect x='90' y='282' width='580' height='34' rx='10' fill='#fef3c7' stroke='#d97706' stroke-width='1.5'/><text x='380' y='304' text-anchor='middle' font-size='12' font-weight='700' fill='#92400e'>Dikkat: Mind sorularında NO cevabı olumlu anlam taşır!</text></svg>", 'b3': "<svg viewBox='0 0 760 320' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='320' rx='16' fill='#f8fafc'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='700' fill='#0f172a'>Responding to a Request: Accept or Refuse Politely</text><rect x='30' y='46' width='700' height='60' rx='12' fill='#dcfce7' stroke='#16a34a' stroke-width='2'/><text x='380' y='70' text-anchor='middle' font-size='13' font-weight='700' fill='#166534'>ACCEPTING: Sure! / Of course. / No problem. / I'd be happy to.</text><text x='380' y='92' text-anchor='middle' font-size='12' fill='#166534'>with a condition: Sure, as long as you give it back by Friday.</text><text x='380' y='132' text-anchor='middle' font-size='13' font-weight='700' fill='#b91c1c'>REFUSING POLITELY IN THREE STEPS</text><rect x='30' y='146' width='210' height='100' rx='12' fill='#ffffff' stroke='#dc2626' stroke-width='2'/><text x='135' y='170' text-anchor='middle' font-size='13' font-weight='700' fill='#991b1b'>1. Soften / Apologize</text><text x='135' y='196' text-anchor='middle' font-size='12' fill='#334155'>I'm sorry, but...</text><text x='135' y='214' text-anchor='middle' font-size='12' fill='#334155'>I'd love to, but...</text><text x='135' y='232' text-anchor='middle' font-size='12' fill='#334155'>I wish I could, but...</text><line x1='244' y1='196' x2='266' y2='196' stroke='#64748b' stroke-width='3'/><polygon points='266,189 280,196 266,203' fill='#64748b'/><rect x='284' y='146' width='210' height='100' rx='12' fill='#ffffff' stroke='#ea580c' stroke-width='2'/><text x='389' y='170' text-anchor='middle' font-size='13' font-weight='700' fill='#9a3412'>2. Give a Reason</text><text x='389' y='196' text-anchor='middle' font-size='12' fill='#334155'>...I have a mock exam</text><text x='389' y='214' text-anchor='middle' font-size='12' fill='#334155'>on Saturday morning.</text><text x='389' y='232' text-anchor='middle' font-size='11' fill='#9a3412'>(gerekçe: because / since)</text><line x1='498' y1='196' x2='520' y2='196' stroke='#64748b' stroke-width='3'/><polygon points='520,189 534,196 520,203' fill='#64748b'/><rect x='538' y='146' width='192' height='100' rx='12' fill='#ffffff' stroke='#2563eb' stroke-width='2'/><text x='634' y='170' text-anchor='middle' font-size='13' font-weight='700' fill='#1e3a8a'>3. Offer an Alternative</text><text x='634' y='196' text-anchor='middle' font-size='12' fill='#334155'>How about Saturday</text><text x='634' y='214' text-anchor='middle' font-size='12' fill='#334155'>afternoon?</text><text x='634' y='232' text-anchor='middle' font-size='11' fill='#1e3a8a'>(alternatif öneri)</text><rect x='90' y='262' width='580' height='40' rx='10' fill='#fee2e2'/><text x='380' y='287' text-anchor='middle' font-size='12' font-weight='700' fill='#b91c1c'>Kaba: No, I won't.  →  Kibar: I'm afraid I can't, but maybe I could help tomorrow.</text></svg>", 'b4': "<svg viewBox='0 0 760 340' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='340' rx='16' fill='#f8fafc'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='700' fill='#065f46'>Saying Thank You and Responding</text><text x='190' y='58' text-anchor='middle' font-size='13' font-weight='700' fill='#475569'>Thanking (Teşekkür)</text><text x='570' y='58' text-anchor='middle' font-size='13' font-weight='700' fill='#475569'>Responding (Karşılık)</text><rect x='40' y='70' width='300' height='34' rx='10' fill='#ecfdf5' stroke='#10b981' stroke-width='1.5'/><text x='190' y='92' text-anchor='middle' font-size='12' fill='#065f46'>Thanks a lot!</text><rect x='420' y='70' width='300' height='34' rx='10' fill='#eff6ff' stroke='#3b82f6' stroke-width='1.5'/><text x='570' y='92' text-anchor='middle' font-size='12' fill='#1e3a8a'>No problem. / No worries.</text><rect x='40' y='112' width='300' height='34' rx='10' fill='#ecfdf5' stroke='#10b981' stroke-width='1.5'/><text x='190' y='134' text-anchor='middle' font-size='12' fill='#065f46'>I owe you one.</text><rect x='420' y='112' width='300' height='34' rx='10' fill='#eff6ff' stroke='#3b82f6' stroke-width='1.5'/><text x='570' y='134' text-anchor='middle' font-size='12' fill='#1e3a8a'>Any time.</text><rect x='40' y='154' width='300' height='34' rx='10' fill='#d1fae5' stroke='#10b981' stroke-width='1.5'/><text x='190' y='176' text-anchor='middle' font-size='12' fill='#065f46'>That's very kind of you.</text><rect x='420' y='154' width='300' height='34' rx='10' fill='#dbeafe' stroke='#3b82f6' stroke-width='1.5'/><text x='570' y='176' text-anchor='middle' font-size='12' fill='#1e3a8a'>Don't mention it.</text><rect x='40' y='196' width='300' height='34' rx='10' fill='#a7f3d0' stroke='#10b981' stroke-width='1.5'/><text x='190' y='218' text-anchor='middle' font-size='12' fill='#065f46'>I really appreciate your help.</text><rect x='420' y='196' width='300' height='34' rx='10' fill='#bfdbfe' stroke='#3b82f6' stroke-width='1.5'/><text x='570' y='218' text-anchor='middle' font-size='12' fill='#1e3a8a'>My pleasure.</text><rect x='40' y='238' width='300' height='34' rx='10' fill='#6ee7b7' stroke='#059669' stroke-width='1.5'/><text x='190' y='260' text-anchor='middle' font-size='12' fill='#064e3b'>I'm very grateful for your support.</text><rect x='420' y='238' width='300' height='34' rx='10' fill='#93c5fd' stroke='#2563eb' stroke-width='1.5'/><text x='570' y='260' text-anchor='middle' font-size='12' fill='#1e3a8a'>It was the least I could do.</text><line x1='346' y1='87' x2='404' y2='87' stroke='#64748b' stroke-width='2'/><polygon points='404,82 414,87 404,92' fill='#64748b'/><line x1='346' y1='129' x2='404' y2='129' stroke='#64748b' stroke-width='2'/><polygon points='404,124 414,129 404,134' fill='#64748b'/><line x1='346' y1='171' x2='404' y2='171' stroke='#64748b' stroke-width='2'/><polygon points='404,166 414,171 404,176' fill='#64748b'/><line x1='346' y1='213' x2='404' y2='213' stroke='#64748b' stroke-width='2'/><polygon points='404,208 414,213 404,218' fill='#64748b'/><line x1='346' y1='255' x2='404' y2='255' stroke='#64748b' stroke-width='2'/><polygon points='404,250 414,255 404,260' fill='#64748b'/><line x1='24' y1='76' x2='24' y2='268' stroke='#94a3b8' stroke-width='3'/><polygon points='18,268 24,282 30,268' fill='#94a3b8'/><text x='380' y='306' text-anchor='middle' font-size='12' font-weight='700' fill='#475569'>Yukarıdan aşağıya: samimi (informal) → resmî (formal)</text><text x='380' y='326' text-anchor='middle' font-size='11' fill='#64748b'>Thank you for + V-ing: Thank you for helping me.</text></svg>", 'b5': "<svg viewBox='0 0 760 330' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='330' rx='16' fill='#f8fafc'/><text x='380' y='30' text-anchor='middle' font-size='16' font-weight='700' fill='#1e3a8a'>LEND or BORROW? and FAVOR Collocations</text><circle cx='100' cy='110' r='38' fill='#dbeafe' stroke='#2563eb' stroke-width='2'/><text x='100' y='115' text-anchor='middle' font-size='14' font-weight='700' fill='#1e3a8a'>Ece</text><circle cx='420' cy='110' r='38' fill='#fef3c7' stroke='#d97706' stroke-width='2'/><text x='420' y='115' text-anchor='middle' font-size='14' font-weight='700' fill='#92400e'>Can</text><rect x='232' y='92' width='56' height='36' rx='6' fill='#ffffff' stroke='#64748b' stroke-width='2'/><text x='260' y='115' text-anchor='middle' font-size='11' font-weight='700' fill='#334155'>BOOK</text><line x1='144' y1='110' x2='224' y2='110' stroke='#16a34a' stroke-width='3'/><polygon points='224,103 232,110 224,117' fill='#16a34a'/><line x1='296' y1='110' x2='370' y2='110' stroke='#16a34a' stroke-width='3'/><polygon points='370,103 380,110 370,117' fill='#16a34a'/><rect x='30' y='166' width='460' height='40' rx='10' fill='#dcfce7'/><text x='260' y='191' text-anchor='middle' font-size='13' fill='#166534'>Ece LENDS her book TO Can. (ödünç verir)</text><rect x='30' y='214' width='460' height='40' rx='10' fill='#fef3c7'/><text x='260' y='239' text-anchor='middle' font-size='13' fill='#92400e'>Can BORROWS the book FROM Ece. (ödünç alır)</text><rect x='30' y='264' width='460' height='50' rx='10' fill='#ffffff' stroke='#94a3b8' stroke-width='1.5'/><text x='260' y='285' text-anchor='middle' font-size='12' fill='#334155'>Can you lend me your book? = Can I borrow your book?</text><text x='260' y='304' text-anchor='middle' font-size='12' font-weight='700' fill='#b91c1c'>Yanlış: Can you borrow me your book?</text><rect x='516' y='56' width='220' height='258' rx='12' fill='#ffffff' stroke='#7c3aed' stroke-width='2'/><rect x='516' y='56' width='220' height='32' rx='12' fill='#7c3aed'/><text x='626' y='77' text-anchor='middle' font-size='13' font-weight='700' fill='#ffffff'>FAVOR Collocations</text><text x='532' y='112' font-size='12' font-weight='700' fill='#4c1d95'>do someone a favor</text><text x='532' y='128' font-size='11' fill='#475569'>iyilik yapmak</text><text x='532' y='154' font-size='12' font-weight='700' fill='#4c1d95'>ask someone a favor</text><text x='532' y='170' font-size='11' fill='#475569'>iyilik istemek</text><text x='532' y='196' font-size='12' font-weight='700' fill='#4c1d95'>owe someone a favor</text><text x='532' y='212' font-size='11' fill='#475569'>iyilik borçlu olmak</text><text x='532' y='238' font-size='12' font-weight='700' fill='#4c1d95'>return the favor</text><text x='532' y='254' font-size='11' fill='#475569'>iyiliğe karşılık vermek</text><text x='532' y='284' font-size='12' font-weight='700' fill='#b91c1c'>make a favor (yanlış)</text><line x1='530' y1='280' x2='660' y2='280' stroke='#b91c1c' stroke-width='2'/></svg>", 'b6': "<svg viewBox='0 0 760 360' xmlns='http://www.w3.org/2000/svg' font-family='Arial, sans-serif'><rect width='760' height='360' rx='16' fill='#f8fafc'/><text x='380' y='28' text-anchor='middle' font-size='16' font-weight='700' fill='#1e3a8a'>Structure of a Formal Request E-mail</text><rect x='30' y='44' width='700' height='300' rx='14' fill='#ffffff' stroke='#94a3b8' stroke-width='2'/><rect x='30' y='44' width='700' height='30' rx='14' fill='#e2e8f0'/><circle cx='52' cy='59' r='6' fill='#ef4444'/><circle cx='72' cy='59' r='6' fill='#f59e0b'/><circle cx='92' cy='59' r='6' fill='#22c55e'/><text x='380' y='64' text-anchor='middle' font-size='12' font-weight='700' fill='#334155'>New Message</text><rect x='46' y='84' width='190' height='30' rx='8' fill='#dbeafe'/><text x='141' y='104' text-anchor='middle' font-size='12' font-weight='700' fill='#1e3a8a'>1. Subject line</text><text x='252' y='104' font-size='12' fill='#334155'>Request to use the school library</text><rect x='46' y='120' width='190' height='30' rx='8' fill='#e0e7ff'/><text x='141' y='140' text-anchor='middle' font-size='12' font-weight='700' fill='#312e81'>2. Greeting</text><text x='252' y='140' font-size='12' fill='#334155'>Dear Mr Aksoy,</text><rect x='46' y='156' width='190' height='30' rx='8' fill='#ede9fe'/><text x='141' y='176' text-anchor='middle' font-size='12' font-weight='700' fill='#4c1d95'>3. Purpose</text><text x='252' y='176' font-size='12' fill='#334155'>I am writing to ask whether it would be possible to...</text><rect x='46' y='192' width='190' height='30' rx='8' fill='#fae8ff'/><text x='141' y='212' text-anchor='middle' font-size='12' font-weight='700' fill='#701a75'>4. Reason / Details</text><text x='252' y='212' font-size='12' fill='#334155'>As I am preparing for the university entrance exam, ...</text><rect x='46' y='228' width='190' height='30' rx='8' fill='#fce7f3'/><text x='141' y='248' text-anchor='middle' font-size='12' font-weight='700' fill='#831843'>5. The request</text><text x='252' y='248' font-size='12' fill='#334155'>I would be grateful if you could let us study there.</text><rect x='46' y='264' width='190' height='30' rx='8' fill='#dcfce7'/><text x='141' y='284' text-anchor='middle' font-size='12' font-weight='700' fill='#166534'>6. Thanks</text><text x='252' y='284' font-size='12' fill='#334155'>Thank you in advance for considering my request.</text><rect x='46' y='300' width='190' height='30' rx='8' fill='#fef3c7'/><text x='141' y='320' text-anchor='middle' font-size='12' font-weight='700' fill='#92400e'>7. Closing</text><text x='252' y='320' font-size='12' fill='#334155'>I look forward to hearing from you. Yours sincerely, Elif</text></svg>"}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
